@Service
public class ImportService {
    private final RowRepository repository;

    public void importAll(List<Row> rows) {
        saveRows(rows);   // this.saveRows(rows)
    }

    @Transactional
    public void saveRows(List<Row> rows) {
        for (Row row : rows) {
            repository.save(row);
        }
    }
}
